//! ⚖️ Canonical error receipt debit preserves both original owner causes without local heap births.
use super::*;
fn observer<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_guest_failure_debit_conserves_external_child_receipts_and_original_cause_pointers(){
 let inputs:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📥️inputs.json")).unwrap();let expected:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📤️expected.json")).unwrap();let closing:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️grants.json")).unwrap();let close:RetainedCloneGrant=serde_json::from_value(closing["close"].clone()).unwrap();let denied:RetainedCloneGrant=serde_json::from_value(closing["denied"].clone()).unwrap();
 for(index,input)in inputs.as_array().unwrap().iter().enumerate(){let policy:RetainedCloneGrant=serde_json::from_value(input["grant"].clone()).unwrap();let mut recipient:RetainedCloneProgress=serde_json::from_value(input["recipient"].clone()).unwrap();let child:RetainedCloneProgress=serde_json::from_value(input["originalReceipt"].clone()).unwrap();let received:RetainedCloneProgress=serde_json::from_value(expected[index]["recipient"].clone()).unwrap();let fuel=input["fuel"].as_u64().unwrap();let mut sequence=0;let token=semio_framework_job::root_cancel_token();let mut cx=StepContext::new(semio_framework_job::OperationId(71),semio_framework_job::Generation(3),StepBudget::new(fuel,u64::MAX,policy),token,semio_framework_job::logical_now_us,&mut sequence,&mut recipient);let mut entry=OriginalActorGuestEntry::new();let(cause,heap)=observer(||ValueError::new(ValueRefusalKind::AllocationFailed,"whole original child cause 世界").with_retained_progress(child));let pointer=cause.message.as_ptr();
  let(accepted,observed)=observer(||OriginalActorGuestEntry::debit_original_error(cause,&mut entry.close_fault,&mut cx));assert_eq!(observed,(0,0));assert_eq!(accepted,expected[index]["accepted"].as_bool().unwrap());assert_eq!(cx.retained_progress(),received);assert_eq!(cx.fuel_remaining(),expected[index]["fuel"].as_u64().unwrap());assert_eq!(entry.original_close_fault().unwrap().message.as_ptr(),pointer);assert_eq!(entry.original_close_fault().unwrap().retained_progress(),child);if !accepted{let debit=entry.original_debit_fault().unwrap();assert_eq!(debit.kind,ValueRefusalKind::InvariantViolated);assert_eq!(debit.retained_progress(),child);assert!(matches!(debit.message,std::borrow::Cow::Borrowed(_)));}else{assert!(entry.original_debit_fault().is_none());}let(step,observed)=observer(||entry.close_failure_step(denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(observed,(0,0));assert_eq!(entry.original_close_fault().unwrap().message.as_ptr(),pointer);
  let(mut allocated,mut released)=heap;for _ in 0..4096{if entry.terminal_is_empty(){break}let(step,observed)=observer(||entry.close_failure_step(close).unwrap());assert!(step.progress().fits(close));assert_eq!(observed,(step.progress().retained_capacity_bytes,step.progress().released_bytes));allocated+=observed.0;released+=observed.1;}assert!(entry.terminal_is_empty());assert_eq!(allocated,released);assert_eq!(observer(||drop(entry)).1,(0,0));
 }
}
